import 'package:cloud_firestore/cloud_firestore.dart';

DateTime _date(dynamic v)=>v is Timestamp?v.toDate():DateTime.tryParse('$v')??DateTime.now();
class PlanItem { final String id,type,title,note,category; final DateTime when; final int before,notificationId; final bool done; PlanItem({required this.id,required this.type,required this.title,required this.note,required this.category,required this.when,required this.before,required this.notificationId,required this.done}); factory PlanItem.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final x=d.data()??{};return PlanItem(id:d.id,type:x['type']??'Task',title:x['title']??'',note:x['note']??'',category:x['category']??'Personal',when:_date(x['when']),before:x['before']??10,notificationId:x['notificationId']??0,done:x['done']==true);} }
class MemoryItem { final String id,title,story,mediaUrl,mediaType; final DateTime createdAt; final bool favorite; MemoryItem({required this.id,required this.title,required this.story,required this.mediaUrl,required this.mediaType,required this.createdAt,required this.favorite}); factory MemoryItem.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final x=d.data()??{};return MemoryItem(id:d.id,title:x['title']??'Memory',story:x['story']??'',mediaUrl:x['mediaUrl']??'',mediaType:x['mediaType']??'note',createdAt:_date(x['createdAt']),favorite:x['favorite']==true);} }
